import shutil

from pyspark.sql import functions as F


class Dashboard:
    # Stands in for the tracking dashboard. Don't change this.
    # It is restarting: the first 2 calls of a run time out, and every call after that answers.
    def __init__(self):
        self.calls = 0
        self.published = []

    def publish(self, day, rows):
        self.calls += 1
        if self.calls <= 2:
            raise TimeoutError("the dashboard did not answer")
        self.published.append(day)


def load_day(batch, day, path, dashboard):
    # Adds one day's events to the tracking table, then tells the dashboard how many arrived.
    batch.write.mode("append").partitionBy("load_date").parquet(path)
    dashboard.publish(day, batch.count())


def solve(shipment_events):
    path = "/tmp/tracking/events"
    shutil.rmtree(path, ignore_errors=True)  # start from an empty table on every run
    dashboard = Dashboard()
    days = sorted(row["load_date"] for row in shipment_events.select("load_date").distinct().collect())
    for day in days:
        load_day(shipment_events.filter(F.col("load_date") == day), day, path, dashboard)
    if not days:
        return spark.createDataFrame([], "event_id STRING, shipment_id STRING, event_type STRING, load_date DATE, published BOOLEAN")
    table = spark.read.parquet(path).select("event_id", "shipment_id", "event_type", "load_date")
    return table.withColumn("published", F.col("load_date").isin(dashboard.published))
